/* 固定容量的火花、弹壳、烟雾、弹痕与曳光，避免射击时频繁创建 GPU 对象。 */
(function(H){
  'use strict';const T=THREE;
  H.createEffects=function(scene,world){
    const dummy=new T.Object3D(),zero=new T.Matrix4().makeScale(0,0,0),up=new T.Vector3(0,0,1),color=new T.Color(),pool=[];let cursor=0,decalIndex=0,quality='medium';
    function inst(geo,mat,count){const m=new T.InstancedMesh(geo,mat,count);m.instanceMatrix.setUsage(T.DynamicDrawUsage);m.frustumCulled=false;m.count=0;scene.add(m);return m;}
    const sparks=inst(new T.BoxGeometry(1,1,1),new T.MeshBasicMaterial({color:'#ffd08a'}),192);
    const shells=inst(new T.CylinderGeometry(.008,.009,.037,7),new T.MeshStandardMaterial({color:'#a99155',metalness:.8,roughness:.35}),72);shells.receiveShadow=true;
    const smokeMat=new T.ShaderMaterial({transparent:true,depthWrite:false,uniforms:{sun:{value:H.sunDirection}},vertexShader:'varying vec2 vUv;varying float vAlpha;attribute float alpha;void main(){vUv=uv;vAlpha=alpha;gl_Position=projectionMatrix*modelViewMatrix*instanceMatrix*vec4(position,1.);}',fragmentShader:`varying vec2 vUv;varying float vAlpha;uniform vec3 sun;${H.glslNoise}void main(){vec2 p=vUv*2.-1.;float n=hFbm(vUv*8.),r=length(p)+(n-.5)*.3;float a=(1.-smoothstep(.28,.98,r))*vAlpha;if(a<.003)discard;float light=.6+.3*sqrt(max(0.,1.-dot(p,p)))+.16*p.x;gl_FragColor=vec4(vec3(.34,.38,.39)*light,a);}`});
    const smokeGeo=new T.PlaneGeometry(1,1);smokeGeo.setAttribute('alpha',new T.InstancedBufferAttribute(new Float32Array(64),1));const smoke=inst(smokeGeo,smokeMat,64),smokes=Array.from({length:64},()=>({life:0,pos:new T.Vector3(),size:.2}));let puff=0;
    const canvas=document.createElement('canvas');canvas.width=128;canvas.height=128;const ctx=canvas.getContext('2d'),gradient=ctx.createRadialGradient(64,64,2,64,64,62);gradient.addColorStop(0,'#080a0aee');gradient.addColorStop(.22,'#172021aa');gradient.addColorStop(.5,'#33271955');gradient.addColorStop(1,'#33271900');ctx.fillStyle=gradient;ctx.fillRect(0,0,128,128);const decalMap=new T.CanvasTexture(canvas),decalMat=new T.MeshBasicMaterial({map:decalMap,transparent:true,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-3});const decals=inst(new T.PlaneGeometry(1,1),decalMat,96);for(let i=0;i<96;i++)decals.setMatrixAt(i,zero);
    const linePositions=new Float32Array(96*6),lineGeo=new T.BufferGeometry();lineGeo.setAttribute('position',new T.BufferAttribute(linePositions,3).setUsage(T.DynamicDrawUsage));const lines=new T.LineSegments(lineGeo,new T.LineBasicMaterial({color:'#ffcf88',transparent:true,opacity:.75,depthWrite:false}));lines.frustumCulled=false;scene.add(lines);const traces=[];
    const lights=Array.from({length:2},()=>{const l=new T.PointLight('#ffb66a',0,6,2);scene.add(l);return{light:l,life:0};});
    for(let i=0;i<264;i++)pool.push({kind:0,life:0,max:1,pos:new T.Vector3(),vel:new T.Vector3(),size:1,spin:0,bounced:false});
    function particle(kind,pos,vel,life,size){let p;if(kind===1){p=pool[cursor++%192];}else{p=pool[192+(cursor++%72)];}Object.assign(p,{kind,life,max:life,size,spin:Math.random()*6,bounced:false});p.pos.copy(pos);p.vel.copy(vel);}
    function emitSmoke(pos,size=.45){const s=smokes[puff++%64];s.pos.copy(pos);s.life=1.4+Math.random()*.5;s.max=s.life;s.size=size;s.angle=Math.random()*6;}
    const api={setQuality(q){quality=q;},clear(){pool.forEach(p=>p.life=0);smokes.forEach(p=>p.life=0);traces.length=0;decalIndex=0;decals.count=0;sparks.count=shells.count=smoke.count=0;lineGeo.setDrawRange(0,0);},
      tracer(from,to){if(traces.length<96)traces.push({from:from.clone(),to:to.clone(),life:.055});},
      shell(pos,velocity){particle(2,pos,velocity,.9+Math.random()*1.4,1);},smoke:emitSmoke,
      flash(pos,power=20){const f=lights.find(x=>x.life<=0)||lights[0];f.light.position.copy(pos);f.life=.06;f.light.intensity=power;},
      burst(pos,amount=12,big=false){const count=quality==='low'?Math.ceil(amount*.5):amount;for(let i=0;i<count;i++)particle(1,pos,new T.Vector3((Math.random()-.5)*(big?8:4),Math.random()*(big?6:3),(Math.random()-.5)*(big?8:4)),.25+Math.random()*.55,.015+Math.random()*.025);if(big){for(let i=0;i<5;i++)emitSmoke(pos,.5+Math.random()*.6);api.flash(pos,35);}},
      impact(pos,normal,surface='metal'){const wet=normal.y>.8&&world.terrain.wetAt(pos.x,pos.z)>.65;const metal=surface==='metal';for(let i=0;i<(quality==='low'?4:metal?13:6);i++){const v=new T.Vector3((Math.random()-.5)*4,Math.random()*3,(Math.random()-.5)*4).addScaledVector(normal,2);particle(1,pos,v,.15+Math.random()*.35,metal?.012:.022);}emitSmoke(pos,wet?.18:.32);
        dummy.position.copy(pos).addScaledVector(normal,.008);dummy.quaternion.setFromUnitVectors(up,normal);dummy.rotateZ(Math.random()*6);dummy.scale.setScalar(wet?.10:metal?.10:.18);dummy.updateMatrix();decals.setMatrixAt(decalIndex++%96,dummy.matrix);decals.count=Math.min(96,decalIndex);decals.instanceMatrix.needsUpdate=true;},
      update(dt,camera){let ns=0,nc=0;for(const p of pool){if(p.life<=0)continue;p.life-=dt;if(p.life<=0)continue;p.vel.y-=dt*(p.kind===2?9.8:8.);p.pos.addScaledVector(p.vel,dt);if(p.pos.y<.035){p.pos.y=.035;p.vel.y=Math.abs(p.vel.y)*.32;p.vel.x*=.65;p.vel.z*=.65;if(p.kind===2&&!p.bounced){p.bounced=true;api.onShellBounce?.(p.pos);}}
          dummy.position.copy(p.pos);dummy.rotation.set(p.spin+p.life*12,p.life*8,p.spin);const fade=Math.min(1,p.life/.15);if(p.kind===1){dummy.scale.set(p.size*fade,p.size*4*fade,p.size*fade);dummy.updateMatrix();sparks.setMatrixAt(ns++,dummy.matrix);}else{dummy.scale.setScalar(fade);dummy.updateMatrix();shells.setMatrixAt(nc++,dummy.matrix);}}
        sparks.count=ns;shells.count=nc;if(ns)sparks.instanceMatrix.needsUpdate=true;if(nc)shells.instanceMatrix.needsUpdate=true;
        const live=smokes.filter(p=>p.life>0).sort((a,b)=>b.pos.distanceToSquared(camera.position)-a.pos.distanceToSquared(camera.position));let k=0;for(const s of live){s.life-=dt;s.pos.y+=dt*.35;s.pos.x+=dt*.1;const age=1-s.life/s.max;dummy.position.copy(s.pos);dummy.quaternion.copy(camera.quaternion);dummy.rotateZ(s.angle);dummy.scale.setScalar(s.size*(.5+age*1.8));dummy.updateMatrix();smoke.setMatrixAt(k,dummy.matrix);smokeGeo.attributes.alpha.array[k++]=Math.sin(Math.PI*Math.max(0,age))*.22;}smoke.count=k;if(k){smoke.instanceMatrix.needsUpdate=true;smokeGeo.attributes.alpha.needsUpdate=true;}
        let j=0;for(let i=traces.length-1;i>=0;i--){const t=traces[i];t.life-=dt;if(t.life<=0){traces.splice(i,1);continue;}t.from.toArray(linePositions,j*6);t.to.toArray(linePositions,j*6+3);j++;}lineGeo.setDrawRange(0,j*2);if(j)lineGeo.attributes.position.needsUpdate=true;
        lights.forEach(f=>{f.life-=dt;f.light.intensity=f.life>0?f.light.intensity*.55:0;});},
      stats(){return{sparks:sparks.count,shells:shells.count,smoke:smoke.count,decals:decals.count,tracers:traces.length};}
    };return api;
  };
})(window.Harbor);
